input.command:
cd /tmp/fix-wt && cat > spec/list_room.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); err=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
BOOKINGS=$t bash src/list.sh --room >/dev/null 2>"$err"; rc=$?
[ $rc = 2 ] && [ "$(cat "$err")" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026/11/10 >/dev/null 2>"$err"; rc=$?
[ $rc = 2 ] && [ "$(cat "$err")" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date"; fail=1; }
BOOKINGS=$t bash src/list.sh --room aoi 2026-13-01 >/dev/null 2>"$err"; rc=$?
[ $rc = 2 ] && [ "$(cat "$err")" = 'bad date: 2026-13-01 (expected YYYY-MM-DD)' ] || { echo "list --room with bad date"; fail=1; }
rm -f "$t" "$err"; exit $fail
EOF
bash spec/list_room.spec.sh; echo "RED exit=$?"

